CREATE TABLE IF NOT EXISTS hr_employee(employee_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,employee_code TEXT NOT NULL,employee_name TEXT NOT NULL,department TEXT,designation TEXT,join_date DATE,employment_status TEXT NOT NULL DEFAULT 'ACTIVE',hourly_cost NUMERIC NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_shift(shift_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,shift_code TEXT NOT NULL,shift_name TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,standard_hours NUMERIC NOT NULL DEFAULT 8,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_attendance(attendance_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,employee_id TEXT NOT NULL,work_date DATE NOT NULL,shift_id TEXT,punch_in TIMESTAMP,punch_out TIMESTAMP,status TEXT NOT NULL DEFAULT 'PRESENT',hours NUMERIC NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_labour_allocation(allocation_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,employee_id TEXT NOT NULL,batch_id TEXT NOT NULL,work_date DATE NOT NULL,hours NUMERIC NOT NULL,rate NUMERIC NOT NULL DEFAULT 0,cost NUMERIC NOT NULL DEFAULT 0,approved BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_hr_attendance_emp_date ON hr_attendance(organization_id,entity_id,employee_id,work_date);
CREATE INDEX IF NOT EXISTS ix_hr_allocation_batch ON hr_labour_allocation(organization_id,entity_id,batch_id,work_date);
